CREATE TYPE "user_status" AS ENUM ('pending', 'active', 'disabled');
CREATE TYPE "connection_status" AS ENUM ('pending', 'connected', 'disabled');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL UNIQUE, "password_hash" text NOT NULL, "public_key" text, "status" user_status NOT NULL DEFAULT 'pending', "email_verified_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "last_login_at" timestamptz);
CREATE TABLE "one_time_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "kind" text NOT NULL, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz);
CREATE TABLE "refresh_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "profile_sets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "client_id" uuid NOT NULL, "encrypted_blob" jsonb NOT NULL, "version" integer NOT NULL DEFAULT 1, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "profile_sets_owner_client" ON "profile_sets" ("owner_id", "client_id");
CREATE TABLE "connections" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "requester_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "addressee_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "status" connection_status NOT NULL DEFAULT 'pending', "requester_profile_set_id" uuid REFERENCES "profile_sets"("id") ON DELETE SET NULL, "addressee_profile_set_id" uuid REFERENCES "profile_sets"("id") ON DELETE SET NULL, "requester_key_envelope" jsonb, "addressee_key_envelope" jsonb, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "connections_pair" ON "connections" ("requester_id", "addressee_id");
CREATE TABLE "devices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "push_token" text NOT NULL UNIQUE, "platform" text NOT NULL, "enabled" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now());
